SELECT d.connection_id AS "connection_id?",d.external_message_id AS "external_message_id?",d.destination AS "destination?",d.status AS "delivery_status?",m.id,m.thread_id,m.participant_id,m.text,m.status,m.in_reply_to_message_id,m.created_at,m.format,m.subject,m.invocation_id,COALESCE((SELECT jsonb_agg(jsonb_build_object('id',a.id,'thread_id',a.thread_id,'filename',a.filename,'media_type',a.media_type,'size_bytes',a.size_bytes,'sha256',a.sha256) ORDER BY a.id) FROM chat_message_attachments ma JOIN chat_attachments a ON a.id=ma.attachment_id WHERE ma.message_id=m.id),'[]'::jsonb) AS "attachments!: AttachmentRecords",ARRAY(SELECT participant_id FROM chat_message_targets WHERE message_id=m.id ORDER BY participant_id) AS "targets!" FROM chat_messages m LEFT JOIN chat_message_deliveries d ON d.message_id=m.id WHERE m.id=$1;
